import type { InstrumentationPlan } from "@meshlytics/schema";

const HEADER = `// This file is generated by \`meshlytics instrument\`.
// Re-run that command after changing meshlytics.config.json to regenerate it.
// Do not edit the tracked-route list by hand — edit the config instead.
//
// Usage:
//   import { createClient } from "meshlytics";
//   import { meshlyticsPlan } from "./meshlytics.instrumentation";
//   export const meshlytics = createClient({ plan: meshlyticsPlan, endpoint: "/api/events" });
`;

function renderArray(items: string[], indent: string): string {
  if (items.length === 0) return "[]";
  const lines = items.map((item) => `${indent}  ${item},`).join("\n");
  return `[\n${lines}\n${indent}]`;
}

/**
 * Renders an instrumentation plan into a TypeScript module exporting
 * `meshlyticsPlan`, ready to pass to `createClient({ plan })`.
 *
 * The module deliberately doesn't create the client: where events go
 * (`endpoint`, `transport`), how identity is stored (`storage`) and
 * environment-specific settings belong to the app, and must survive
 * regenerating this file.
 */
export function generateInstrumentationModule(plan: InstrumentationPlan): string {
  const routes = plan.tracked.map(
    (tracked) => `{
      path: ${JSON.stringify(tracked.route.path)},
      params: {
        routeParams: ${tracked.params.routeParams},
        queryParams: ${tracked.params.queryParams},
        utmParams: ${tracked.params.utmParams},
        referrer: ${tracked.params.referrer},
      },
    }`,
  );

  // Untracked discovered routes still have to reach the SDK so a more
  // specific untracked page (/projects/new) isn't counted under a
  // tracked pattern (/projects/[id]).
  const trackedPaths = new Set(plan.tracked.map((tracked) => tracked.route.path));
  const excluded = plan.application.routes
    .map((route) => route.path)
    .filter((path) => !trackedPaths.has(path))
    .map((path) => JSON.stringify(path));

  return `${HEADER}
import type { MeshlyticsPlan } from "meshlytics";

export const meshlyticsPlan: MeshlyticsPlan = {
  version: ${plan.version},
  generatedAt: ${JSON.stringify(plan.generatedAt)},
  application: {
    framework: ${JSON.stringify(plan.application.framework)},
    router: ${JSON.stringify(plan.application.router)},
  },
  routes: ${renderArray(routes, "  ")},
  excludedRoutes: ${renderArray(excluded, "  ")},
};
`;
}
